source='''from collections import Counter

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    # Repeated isolated pixels are placement markers.
    coords={}
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg:
                coords.setdefault(g[r][c],[]).append((r,c))
    singleton_counts={}
    for color, ps in coords.items():
        singleton_counts[color]=sum(
            not any(0<=r+dr<h and 0<=c+dc<w and g[r+dr][c+dc]==color
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))
            for r,c in ps)
    marker=max(singleton_counts, key=singleton_counts.get)
    targets=coords[marker]
    stamp=[(r,c,g[r][c]) for r in range(h) for c in range(w)
           if g[r][c]!=bg and g[r][c]!=marker]
    anchor_color=1 if marker==3 else 0
    anchors=[(r,c) for r,c,v in stamp if v==anchor_color]
    ar,ac=anchors[-1]
    for tr,tc in targets:
        dr,dc=tr-ar,tc-ac
        for r,c,v in stamp:
            rr,cc=r+dr,c+dc
            if 0<=rr<h and 0<=cc<w:
                g[rr][cc]=v
    return g
'''
